package org.sleepwell.app;

import org.junit.Test;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;

public class AutomaticStartTest {
    private final ZoneId zone=ZoneId.of("Asia/Riyadh");
    private long at(String date){return LocalDateTime.parse(date).atZone(zone).toInstant().toEpochMilli();}
    @Test public void bedtimeUsesTheSavedLocalScheduleAndRollsTomorrow(){assertEquals(at("2026-10-23T22:30"),AutomaticStart.schedule(AutomaticSleep.Mode.BEDTIME,at("2026-10-23T21:00"),zone,1350,List.of()));assertEquals(at("2026-10-24T22:30"),AutomaticStart.schedule(AutomaticSleep.Mode.BEDTIME,at("2026-10-23T23:00"),zone,1350,List.of()));}
    @Test public void stillnessStartsLookingNow(){long now=at("2026-10-23T21:00");assertEquals(now,AutomaticStart.schedule(AutomaticSleep.Mode.STILLNESS,now,zone,1350,List.of()));}
    @Test public void smartWindowNeedsARealEnabledAlarm(){try{AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,0,zone,1350,List.of());fail();}catch(IllegalArgumentException expected){}Alarm disabled=new Alarm(1);disabled.enabled=false;disabled.smartWindow=30;try{AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,0,zone,1350,List.of(disabled));fail();}catch(IllegalArgumentException expected){}}
    private Alarm smart(int id,int hour,int minute,int window){Alarm alarm=new Alarm(id);alarm.enabled=true;alarm.hour=hour;alarm.minute=minute;alarm.smartWindow=window;return alarm;}
    @Test public void smartLeadInIsFortyFiveMinutesBeforeTheWindow(){Alarm alarm=smart(1,6,30,30);assertEquals(at("2026-10-23T05:15"),AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,at("2026-10-23T04:00"),zone,1350,List.of(alarm)));}
    @Test public void alreadyOpenLeadInStartsNowInsteadOfWaitingTomorrow(){Alarm alarm=smart(1,6,30,30);long now=at("2026-10-23T05:45");assertEquals(now,AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,now,zone,1350,List.of(alarm)));}
    @Test public void passedAlarmUsesItsNextCalendarOccurrence(){Alarm alarm=smart(1,6,30,30);assertEquals(at("2026-10-24T05:15"),AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,at("2026-10-23T07:00"),zone,1350,List.of(alarm)));}
    @Test public void weeklyAlarmHonorsItsSelectedDays(){Alarm alarm=smart(1,6,30,30);alarm.days.add(6);assertEquals(at("2026-10-24T05:15"),AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,at("2026-10-23T04:00"),zone,1350,List.of(alarm)));}
    @Test public void earliestEnabledSmartWindowWins(){Alarm later=smart(1,8,30,30),earlier=smart(2,6,30,20),disabled=smart(3,5,0,30),fixed=smart(4,4,30,0);disabled.enabled=false;assertEquals(at("2026-10-23T05:25"),AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,at("2026-10-23T03:00"),zone,1350,List.of(later,disabled,fixed,earlier)));}

    @Test public void datedAlarmUsesChosenDateRatherThanTomorrow(){Alarm a=smart(1,6,30,30);a.date=LocalDate.of(2026,10,26);assertEquals(at("2026-10-26T05:15"),AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,at("2026-10-23T04:00"),zone,1350,List.of(a)));}
    @Test public void expiredDatedAlarmCannotTurnIntoATomorrowArm(){Alarm a=smart(1,6,30,30);a.date=LocalDate.of(2026,10,22);assertThrows(IllegalArgumentException.class,()->AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,at("2026-10-23T04:00"),zone,1350,List.of(a)));}
    @Test public void sunriseUsesCalculatedDeadlineNotAcknowledgedFallbackClock(){Alarm a=smart(1,23,0,30);a.solar=new SunriseSchedule(24.7136,46.6753,0,true);long now=at("2026-10-23T03:00"),deadline=a.next(now,zone);int hour=Instant.ofEpochMilli(deadline).atZone(zone).getHour();assertTrue(hour>=5&&hour<8);assertEquals(deadline-75*60000L,AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,now,zone,1350,List.of(a)));}
    @Test public void skippedFridayUsesNextUnskippedWeekday(){Alarm a=smart(1,6,30,30);a.days.addAll(Set.of(1,2,3,4,5));a.skip=new AlarmSkip("d679855a-69a3-4cc9-8a1f-e4906a00ea92",LocalDate.of(2026,10,23),6,30,a.days,zone.getId());assertEquals(at("2026-10-26T05:15"),AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,at("2026-10-23T04:00"),zone,1350,List.of(a)));}
    @Test public void calendarMeetingProjectionUsesActualAdvancedWakeDeadline(){Alarm a=smart(1,7,0,30);a.days.addAll(Set.of(1,2,3,4,5,6,7));long now=at("2026-10-24T22:00"),meeting=at("2026-10-25T06:30");CalendarPolicy.Rules rules=new CalendarPolicy.Rules(true,Set.of(),Set.of(2L),30,180,"meeting");CalendarPolicy.Snapshot snapshot=new CalendarPolicy.Snapshot(at("2026-10-24T00:00"),at("2026-11-24T00:00"),now,zone,"meeting",List.of(new CalendarPolicy.Event(2,meeting,meeting+3600000,false)));AutomaticStart.Projection projected=(alarm,from,z)->CalendarPolicy.plan(rules,snapshot,from,alarm.next(from,z),z,value->alarm.next(value,z)).deadline;assertEquals(at("2026-10-25T04:45"),AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,now,zone,1350,List.of(a),projected));}
    @Test public void calendarHolidayProjectionDoesNotArmForExcludedDate(){Alarm a=smart(1,6,30,30);a.days.addAll(Set.of(1,2,3,4,5));long now=at("2026-10-22T22:00");CalendarPolicy.Rules rules=new CalendarPolicy.Rules(true,Set.of(1L),Set.of(),30,180,"holiday");CalendarPolicy.Event event=new CalendarPolicy.Event(1,Instant.parse("2026-10-23T00:00:00Z").toEpochMilli(),Instant.parse("2026-10-24T00:00:00Z").toEpochMilli(),true);CalendarPolicy.Snapshot snapshot=new CalendarPolicy.Snapshot(at("2026-10-22T00:00"),at("2026-11-24T00:00"),now,zone,"holiday",List.of(event));assertEquals(at("2026-10-26T05:15"),AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,now,zone,1350,List.of(a),(alarm,from,z)->CalendarPolicy.plan(rules,snapshot,from,alarm.next(from,z),z,value->alarm.next(value,z)).deadline));}
    @Test public void projectedPastMissingOrConsumedDeadlineNeverBackfills(){Alarm a=smart(1,6,30,30);long now=at("2026-10-23T05:45");for(long invalid:new long[]{-1,0,now-1,now})assertThrows(IllegalArgumentException.class,()->AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,now,zone,1350,List.of(a),(alarm,from,z)->invalid));assertEquals(now,AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,now,zone,1350,List.of(a),(alarm,from,z)->now+1));}
    @Test public void relativeNapsAndMalformedSchedulingMetadataAreNotEligible(){Alarm nap=smart(1,6,30,30);nap.nap=new NapPlan("d679855a-69a3-4cc9-8a1f-e4906a00ea92","fixture",1,0,0,20,true,NapPlan.Phase.PENDING,"");Alarm badDate=smart(2,6,30,30);badDate.dateInvalid=true;Alarm badSolar=smart(3,6,30,30);badSolar.solarInvalid=true;Alarm badSkip=smart(4,6,30,30);badSkip.skipInvalid=true;assertThrows(IllegalArgumentException.class,()->AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,at("2026-10-23T04:00"),zone,1350,List.of(nap,badDate,badSolar,badSkip),(alarm,from,z)->{throw new AssertionError("Invalid scheduling metadata cannot reach projection");}));}
    @Test public void daylightGapLeadInUsesActualElapsedDeadline(){ZoneId berlin=ZoneId.of("Europe/Berlin");Alarm a=smart(1,2,30,30);a.date=LocalDate.of(2026,3,29);long now=Instant.parse("2026-03-28T20:00:00Z").toEpochMilli();assertEquals(Instant.parse("2026-03-29T00:15:00Z").toEpochMilli(),AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,now,berlin,1350,List.of(a)));}
    @Test public void consumedOccurrenceFenceSurvivesWallClockRollback(){Alarm a=smart(1,6,30,30);long now=at("2026-10-23T05:00"),consumed=at("2026-10-23T06:30");assertEquals(at("2026-10-24T05:15"),AutomaticStart.schedule(AutomaticSleep.Mode.SMART_WINDOW,now,zone,1350,List.of(a),(alarm,from,z)->alarm.next(Math.max(from,consumed),z)));}
}
